    /// Tests with a log (no set to ask): a kit's variant specs (aot.json `kernels`) that launch-shape choices ask
    /// instead of a set (aot.specsHave; tri_norm.rowmmPartsPiece). Null with a log: every launch resolves, as recorded.
    kit: ?[]const aot.KernelJson = null,

    pub fn run(t: Tri, name: []const u8, grid: [3]u32, args: []const aot.Arg, consts: []const aot.Const) !void {
        if (t.log) |l| return l.add(name, grid, args, consts);
        try t.set.?.run(t.stream, name, grid, args, consts);
    }

    /// Whether a launch resolves (the set's variant, exact or by fallback; a test's kit specs; a bare log: yes): a
    /// wrapper whose launch shape the kit may not hold asks before it launches.
    pub fn has(t: Tri, name: []const u8, args: []const aot.Arg, consts: []const aot.Const) bool {
        if (t.set) |set| return set.has(name, args, consts);
        if (t.kit) |specs| return aot.specsHave(specs, name, args, consts);
        return true;
    }

    /// The PDL constexpr a wrapper passes when its kernel takes one (_pdl() in kernels.py).
    pub fn pdlConst(t: Tri) aot.Const {
        return aot.ci("PDL", @intFromBool(t.pdl));
    }
